def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [b for a, b in history]
    my = [a for a, b in history]
    opp_c = sum(1 for b in opp if b == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for a in my if a == 'C')
    my_d = n - my_c
    last_me = my[-1]
    last_opp = opp[-1]
    rounds_left = 100 - n

    if n == 1:
        return 'C' if last_opp == 'C' else 'C'

    recent_len = 10 if n >= 10 else n
    recent_opp = opp[-recent_len:]
    recent_my = my[-recent_len:]
    recent_opp_c = sum(1 for x in recent_opp if x == 'C')
    recent_opp_rate = recent_opp_c / recent_len
    recent_my_d = sum(1 for x in recent_my if x == 'D')

    overall_opp_rate = opp_c / n

    def_run = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            def_run += 1
        else:
            break

    coop_run = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            coop_run += 1
        else:
            break

    my_def_run = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'D':
            my_def_run += 1
        else:
            break

    my_c_run = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'C':
            my_c_run += 1
        else:
            break

    mutual_cc_run = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'C' and opp[i] == 'C':
            mutual_cc_run += 1
        else:
            break

    alt = 0
    if n >= 4:
        alt_ok = True
        for k in range(n - 4, n):
            if my[k] != opp[k]:
                alt_ok = False
                break
        if alt_ok:
            alt = 1

    if rounds_left <= 1:
        if last_opp == 'C':
            return 'D'
        return 'D'

    if mutual_cc_run >= 2 and last_opp == 'C' and last_me == 'C':
        if opp_d == 0:
            if rounds_left <= 3:
                if rounds_left == 3 and rng.random() < 0.5:
                    return 'D'
                if rounds_left <= 2:
                    return 'D'
                return 'C'
            return 'C'
        if rounds_left <= 4:
            if recent_opp_rate >= 0.8:
                return 'D'
            return 'C'
        return 'C'

    if last_me == 'D' and last_opp == 'C':
        if coop_run >= 1 and recent_opp_rate >= 0.6:
            return 'C'
        if rounds_left <= 3:
            return 'C'
        return 'C'

    if last_opp == 'C':
        if overall_opp_rate >= 0.85 and recent_opp_rate >= 0.7:
            if def_run >= 1 and n >= 8:
                return 'D' if rng.random() < 0.6 else 'D'
            if rounds_left > 5:
                return 'C'
            return 'D' if rng.random() < 0.7 else 'C'
        if recent_opp_rate >= 0.6:
            if rounds_left <= 5:
                return 'D' if rng.random() < 0.6 else 'C'
            return 'C'
        if recent_opp_rate >= 0.4:
            if rounds_left <= 4:
                return 'D'
            return 'C'
        if rounds_left <= 6:
            return 'D'
        return 'C'

    if def_run >= 1:
        if def_run == 1:
            if overall_opp_rate >= 0.6:
                return 'D'
            if recent_opp_rate >= 0.5:
                return 'D'
            return 'D'
        if def_run == 2:
            if overall_opp_rate >= 0.5:
                return 'D'
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        if def_run >= 3:
            if overall_opp_rate >= 0.4:
                if rng.random() < 0.08 and rounds_left > 10:
                    return 'C'
                return 'D'
            if rng.random() < 0.15 and rounds_left > 10:
                return 'C'
            return 'D'

    if last_opp == 'D':
        if overall_opp_rate >= 0.7:
            return 'D'
        if recent_opp_rate >= 0.5:
            return 'D'
        if rounds_left <= 6:
            return 'D'
        return 'D'

    return 'C'
